import React, { useState } from 'react';
import Form from '@rjsf/core';
import validator from '@rjsf/validator-ajv8';
import axios from 'axios';

const schema = {
  type: "object",
  required: ["topic", "question_content", "options", "correct_option_index", "stake_amount"],
  properties: {
    topic: { type: "string", title: "CHỦ ĐỀ", enum: ["Grammar", "Vocabulary", "Reading", "Idioms"] },
    question_content: { type: "string", title: "CÂU HỎI (TIẾNG ANH)", minLength: 10 },
    options: { 
      type: "array", title: "CÁC LỰA CHỌN", minItems: 4, maxItems: 4, 
      items: { type: "string", default: "" } 
    },
    correct_option_index: { 
      type: "integer", title: "ĐÁP ÁN ĐÚNG (0-3)", enum: [0, 1, 2, 3],
      enumNames: ["Lựa chọn 1", "Lựa chọn 2", "Lựa chọn 3", "Lựa chọn 4"] 
    },
    stake_amount: { type: "integer", title: "MỨC CƯỢC (TOKEN)", default: 5, minimum: 1 }
  }
};

const uiSchema = {
  question_content: { "ui:widget": "textarea", "ui:options": { rows: 3 } },
  stake_amount: { "ui:widget": "updown" }
};

const CreatorStudio = ({ currentAccount }) => {
  const [loading, setLoading] = useState(false);
  const [feedback, setFeedback] = useState(null);

  const onSubmit = async ({ formData }) => {
    if (!currentAccount) return alert("⚠️ Vui lòng kết nối ví trước!");
    
    setLoading(true);
    setFeedback(null);

    try {
      const payload = { ...formData, creator_address: currentAccount };
      const res = await axios.post('http://localhost:5000/api/exercises/create', payload);
      
      setFeedback({
        type: res.data.success ? 'success' : 'error',
        message: res.data.message
      });
    } catch (err) {
      setFeedback({ type: 'error', message: 'Lỗi kết nối Server hoặc AI quá tải.' });
    }
    setLoading(false);
  };

  return (
    <div className="min-h-screen flex items-center justify-center p-4">
      <div className="glass-panel w-full max-w-3xl rounded-2xl p-8">
        <div className="flex items-center justify-between mb-6 border-b pb-4">
          <div>
            <h2 className="text-3xl font-bold text-gray-800">✨ Creator Studio</h2>
            <p className="text-gray-500">Tạo nội dung & Kiếm tiền thụ động</p>
          </div>
          <div className="bg-indigo-100 text-indigo-700 px-4 py-2 rounded-full text-sm font-bold">
            🤖 AI Powered
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
          {/* Cột trái: Hướng dẫn */}
          <div className="md:col-span-1 space-y-4">
            <div className="bg-blue-50 p-4 rounded-lg border border-blue-100">
              <h4 className="font-bold text-blue-800 mb-2">💡 Cơ chế kiếm tiền</h4>
              <p className="text-sm text-blue-600">
                Khi người học trả lời <b>SAI</b> câu hỏi của bạn, số token họ cược sẽ chuyển về ví của bạn.
              </p>
            </div>
            <div className="bg-purple-50 p-4 rounded-lg border border-purple-100">
              <h4 className="font-bold text-purple-800 mb-2">🛡️ AI Kiểm duyệt</h4>
              <p className="text-sm text-purple-600">
                Mọi bài đăng đều được ChatGPT kiểm tra chất lượng trước khi lên sàn.
              </p>
            </div>
          </div>

          {/* Cột phải: Form */}
          <div className="md:col-span-2">
            <Form 
              schema={schema} 
              uiSchema={uiSchema} 
              validator={validator} 
              onSubmit={onSubmit}
              className="rjsf-custom"
            >
              <div className="mt-6">
                {loading ? (
                  <button disabled className="w-full py-3 rounded-lg bg-gray-400 text-white font-bold cursor-wait flex justify-center items-center gap-2">
                    <span className="animate-spin text-xl">⏳</span> Đang hỏi ý kiến AI...
                  </button>
                ) : (
                  <button type="submit" className="w-full py-3 rounded-lg btn-gradient font-bold shadow-lg">
                    🚀 Gửi bài lên Blockchain
                  </button>
                )}
              </div>
            </Form>

            {feedback && (
              <div className={`mt-6 p-4 rounded-lg border flex items-center gap-3 animate-bounce ${
                feedback.type === 'success' ? 'bg-green-50 border-green-200 text-green-700' : 'bg-red-50 border-red-200 text-red-700'
              }`}>
                <span className="text-2xl">{feedback.type === 'success' ? '🎉' : '🤖'}</span>
                <div>
                  <p className="font-bold">{feedback.type === 'success' ? 'Thành công!' : 'AI Từ chối'}</p>
                  <p className="text-sm">{feedback.message}</p>
                </div>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
};

export default CreatorStudio;
